const score=(inlet_vials,outlet_vials,reagent_cartridges,assay_benches,contamination_alert)=>{
  const effort=inlet_vials*11+outlet_vials*7+reagent_cartridges*9+(contamination_alert?reagent_cartridges*4:0);
  const allowance=assay_benches*52;
  const examined=Math.min(effort,allowance);
  const pending=Math.max(effort-allowance,0);
  const cycles=Math.ceil(effort/27);
  return examined+pending*4+cycles*8;
};
export async function loadParley(){return {estuary_assay_rating:(...args)=>BigInt(score(...args))}}

