import json,os
from pathlib import Path
from fastapi import FastAPI,Request
from fastapi.responses import FileResponse,JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import ValidationError
from logic import RequestInput,calculate
def zero(v:RequestInput,state:str)->dict[str,object]: return {'clearance_slug':v.clearance_slug,'payload_tally':0,'transfer_effort':0,'berth_allowance':0,'approved_effort':0,'spillover_effort':0,'orbit_passes':0,'clearance_rating':0,'clearance_phase':state}
def decide(v:RequestInput,request:Request)->JSONResponse:
    if request.headers.get('x-orbit-credential','') != 'orbit-046': return outcome(zero(v,'authorization_required'),403,{'x-access-denial': 'orbit_credential'})
    if any(item < 0 for item in (v.pressurized_pods,v.vacuum_pods,v.docking_arms,)): return outcome(zero(v,'invalid'),422,{'x-validation':'nonnegative'})
    if v.docking_arms==0 and v.pressurized_pods+v.vacuum_pods>0: return outcome(zero(v,'invalid'),422,{'x-validation':'docking_arms'})
    body=calculate(v)
    phase=str(body['clearance_phase'])
    return outcome(body,207,{'location':f'/api/v10/orbital-clearances/{v.clearance_slug}','x-clearance-phase':phase})

