const score=(pressurized_pods,vacuum_pods,docking_arms,solar_flare)=>{
  const total=pressurized_pods+vacuum_pods;
  const effort=pressurized_pods*8+vacuum_pods*14+(solar_flare?docking_arms*5:0);
  const allowance=docking_arms*47;
  const approved=Math.min(effort,allowance);
  const spillover=Math.max(effort-allowance,0);
  const passes=Math.ceil(total/4);
  return approved+spillover*7+passes*6;
};
