def zero(v:RequestInput,state:str)->dict[str,object]: return {'assay_ref':v.assay_ref,'sample_tally':0,'assay_effort':0,'bench_allowance':0,'examined_effort':0,'pending_assay':0,'assay_cycles':0,'assay_rating':0,'assay_phase':state}
def decide(v:RequestInput,request:Request)->JSONResponse:
    if request.headers.get('authorization','') != 'Sample sample-046': return outcome(zero(v,'authorization_required'),401,{'www-authenticate': 'Sample realm=estuary'})
    if any(item < 0 for item in (v.inlet_vials,v.outlet_vials,v.reagent_cartridges,v.assay_benches,)): return outcome(zero(v,'invalid'),422,{'x-validation':'nonnegative'})
    if v.assay_benches==0 and v.inlet_vials+v.outlet_vials>0: return outcome(zero(v,'invalid'),422,{'x-validation':'assay_benches'})
    if v.repeated_submission: return outcome(zero(v,'duplicate'),409,{'x-conflict':'repeated_submission'})
    body=calculate(v)
    return outcome(body,202,{'location':f'/api/v10/estuary-assays/{v.assay_ref}','retry-after':'5','x-assay-phase':str(body['assay_phase'])})

MAX_BODY_BYTES=16_384
