from pydantic import BaseModel,ConfigDict
class RequestInput(BaseModel):
    model_config=ConfigDict(extra='forbid',strict=True); assay_ref:str; inlet_vials:int; outlet_vials:int; reagent_cartridges:int; assay_benches:int; contamination_alert:bool; repeated_submission:bool
def score(inlet_vials:int,outlet_vials:int,reagent_cartridges:int,assay_benches:int,contamination_alert:bool)->int:
    effort=inlet_vials*11+outlet_vials*7+reagent_cartridges*9
    if contamination_alert:
        effort+=reagent_cartridges*4
    allowance=assay_benches*52
    examined=min(effort,allowance)
    pending=max(effort-allowance,0)
    cycles=(effort+26)//27
