function score(pressurizedPods,vacuumPods,dockingArms,solarFlare){
  const payloadTally=pressurizedPods+vacuumPods;
  const transferEffort=pressurizedPods*8+vacuumPods*14+(solarFlare?dockingArms*5:0);
  const berthAllowance=dockingArms*47;
  const approvedEffort=Math.min(transferEffort,berthAllowance);
  const spilloverEffort=Math.max(transferEffort-berthAllowance,0);
  const orbitPasses=Math.ceil(payloadTally/4);
  return approvedEffort+spilloverEffort*7+orbitPasses*6;
}
