export type RequestInput={assay_ref:string;inlet_vials:number;outlet_vials:number;reagent_cartridges:number;assay_benches:number;contamination_alert:boolean;repeated_submission:boolean};
export const score=(inlet_vials:number,outlet_vials:number,reagent_cartridges:number,assay_benches:number,contamination_alert:boolean)=>{const effort=inlet_vials*11+outlet_vials*7+reagent_cartridges*9+(contamination_alert?reagent_cartridges*4:0),allowance=assay_benches*52,pending=Math.max(effort-allowance,0),cycles=Math.ceil(effort/27);return Math.min(effort,allowance)+pending*4+cycles*8};
