from __future__ import annotations
import json,os
from pathlib import Path
from fastapi import FastAPI,Request
from fastapi.responses import FileResponse,JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import ValidationError
from logic import RequestInput,calculate
def zero(v:RequestInput,state:str)->dict[str,object]: return {'enrollment_ref':v.enrollment_ref,'transponder_tally':0,'tuning_effort':0,'frame_allowance':0,'commissioned_effort':0,'uncommissioned_effort':0,'tuning_rounds':0,'enrollment_rating':0,'enrollment_phase':state}
def decide(v:RequestInput,request:Request)->JSONResponse:
    if request.headers.get('x-rescue-pass','') != 'beacon-046': return outcome(zero(v,'authorization_required'),403,{'x-access-denial': 'rescue_pass'})
    if any(item < 0 for item in (v.analog_transponders,v.digital_transponders,v.calibration_frames,)): return outcome(zero(v,'invalid'),422,{'x-validation':'nonnegative'})
    if v.calibration_frames==0 and v.analog_transponders+v.digital_transponders>0: return outcome(zero(v,'invalid'),422,{'x-validation':'calibration_frames'})
    body=calculate(v); return outcome(body,201,{'location':f'/api/v10/beacon-enrollments/{v.enrollment_ref}','retry-after':'4','x-enrollment-phase':str(body['enrollment_phase'])})

MAX_BODY_BYTES=16_384
PUBLIC=Path(__file__).with_name('public')
def error(code:str,status:int,detail:str)->JSONResponse: return JSONResponse({'error':code,'detail':detail},status_code=status)
def outcome(body:dict[str,object],status:int,headers:dict[str,str])->JSONResponse:
    if any(name.lower() in {'content-length','content-type','connection','transfer-encoding','x-content-type-options'} for name in headers): return error('invalid_response_headers',500,'server-owned response header')
    return JSONResponse(body,status_code=status,headers=headers)
